public class CursorTickConfigTest
{
	private final CursorTickConfig config = new CursorTickConfig()
	{
	};

	@Test
	public void usesRequestedGeneralDefaults()
	{
		assertEquals(VisibilityMode.LOGGED_IN, config.visibilityMode());
		assertFalse(config.gameViewportOnly());
		assertTrue(config.hideWhenMenuOpen());
		assertEquals(10, config.idleFadeDelaySeconds());
		assertEquals(1, config.idleFadeDurationSeconds());
		assertTrue(config.antiAliasing());
		assertTrue(config.showFeedbackOutline());
	}

	@Test
	public void usesRequestedTimingAndLabelDefaults()
	{
		assertEquals(TimingMode.FIXED, config.timingMode());
		assertEquals(600, config.tickDuration());
		assertEquals(20, config.adaptationStrength());
		assertEquals(0, config.phaseOffset());
		assertFalse(config.pulseOnTick());
		assertEquals(1, config.pulseCycleTick());
		assertEquals(110, config.pulseOnTickDuration());
		assertEquals(4, config.pulseOnTickExpansion());
		assertEquals(new Color(255, 255, 255, 210), config.pulseOnTickColor());
		assertTrue(config.showTickLabel());
		assertEquals(4, config.cycleLength());
		assertTrue(config.cycleStartAccent());
	}

	@Test
	public void usesRequestedClickAndCursorDefaults()
	{
		assertTrue(config.showClickPulse());
		assertEquals(ClickAnchor.CLICK_LOCATION, config.clickAnchor());
		assertEquals(260, config.clickPulseDuration());
		assertEquals(6, config.clickPulseExpansion());
		assertEquals(2, config.clickPulseThickness());
		assertEquals(new Color(80, 190, 255, 230), config.leftClickColor());
		assertEquals(new Color(255, 95, 120, 230), config.rightClickColor());
		assertEquals(new Color(210, 140, 255, 230), config.middleClickColor());
		assertEquals(CursorMode.SYSTEM, config.cursorMode());
		assertTrue(config.fadeOnTickReset());
		assertEquals(180, config.tickResetFadeDuration());
	}
}

package com.cursortickring;

import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class FoodDelayTrackerTest
{
	private final FoodDelayTracker tracker = new FoodDelayTracker();
	private final Item shark = new Item(ItemID.SHARK, 1);
	private final Item karambwan = new Item(ItemID.TBWT_COOKED_KARAMBWAN, 1);

	@Test
	public void confirmsComboEatingOnceEvenWithRepeatedClicks()
	{
		Item[] inventory = {shark, karambwan};
		tracker.clicked(shark.getId(), "Eat", inventory, 10);
		tracker.clicked(shark.getId(), "Eat", inventory, 10);
		tracker.clicked(karambwan.getId(), "Eat", inventory, 10);
		assertEquals(0, tracker.consumed(inventory, 10));
		assertEquals(5, tracker.consumed(new Item[0], 11));
		assertEquals(0, tracker.consumed(new Item[0], 11));
	}

	@Test
	public void ignoresInventoryMovesAndCancelledOrExpiredEating()
	{
		Item[] inventory = {shark, karambwan};
		tracker.clicked(shark.getId(), "Eat", inventory, 10);
		assertEquals(0, tracker.consumed(new Item[]{karambwan, shark}, 11));
		tracker.clicked(shark.getId(), "Drop", inventory, 11);
		assertEquals(0, tracker.consumed(new Item[]{karambwan}, 11));
		tracker.clicked(shark.getId(), "Eat", inventory, 10);
		tracker.expire(13);
		assertEquals(0, tracker.consumed(new Item[]{karambwan}, 13));
	}

	@Test
	public void handlesFoodThatLeavesAnotherPortionAndStackableFood()
	{
		tracker.clicked(ItemID.CAKE, "Eat", new Item[]{new Item(ItemID.CAKE, 1)}, 10);
		assertEquals(3, tracker.consumed(new Item[]{new Item(ItemID.PARTIAL_CAKE, 1)}, 11));
		tracker.clicked(ItemID.TRAIL_SWEETS, "Eat", new Item[]{new Item(ItemID.TRAIL_SWEETS, 8)}, 11);
		assertEquals(3, tracker.consumed(new Item[]{new Item(ItemID.TRAIL_SWEETS, 7)}, 12));
	}

	@Test
	public void drinkingAndResettingDoNotAddFoodDelay()
	{
		Item brew = new Item(ItemID._4DOSEPOTIONOFSARADOMIN, 1);
		tracker.clicked(brew.getId(), "Drink", new Item[]{brew}, 10);
		assertEquals(0, tracker.consumed(new Item[0], 11));
		tracker.clicked(shark.getId(), "Eat", new Item[]{shark}, 10);
		tracker.reset();
		assertEquals(0, tracker.consumed(new Item[0], 11));
		assertEquals(2, FoodDelayTracker.attackDelay(ItemID.BLIGHTED_KARAMBWAN));
		assertEquals(2, FoodDelayTracker.attackDelay(ItemID.HALIBUT));
		assertEquals(2, FoodDelayTracker.attackDelay(ItemID.PREMADE_FRUIT_BATTA));
		assertEquals(2, FoodDelayTracker.attackDelay(ItemID.ALUFT_CHOCOLATE_BOMB));
	}
}

package com.cursortickring;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class TickCycleTest
{
	@Test
	public void startsAtOneAndRepeats()
	{
		TickCycle cycle = new TickCycle();

		assertEquals(0, cycle.positionAt(0L, 4));
		assertEquals(1, cycle.positionAt(1L, 4));
		assertEquals(4, cycle.positionAt(4L, 4));
		assertEquals(1, cycle.positionAt(5L, 4));
	}

	@Test
	public void restartMakesTheCurrentTickPositionOne()
	{
		TickCycle cycle = new TickCycle();
		cycle.restartAt(11L);

		assertEquals(1, cycle.positionAt(11L, 4));
		assertEquals(2, cycle.positionAt(12L, 4));
		assertEquals(1, cycle.positionAt(15L, 4));
	}

	@Test
	public void resetRestoresTheOriginalCycleOrigin()
	{
		TickCycle cycle = new TickCycle();
		cycle.restartAt(7L);
		cycle.reset();

		assertEquals(3, cycle.positionAt(7L, 4));
	}
}

